+bool Bluetooth::internetSharingAvailable() const
+{
+#if HAVE_NETWORKMANAGERQT
+    return NetworkManager::status() != NetworkManager::Unknown;
+#else
+    return false;
+#endif
+}
+
+bool Bluetooth::internetSharing() const
+{
+#if HAVE_NETWORKMANAGERQT
+    const QString uuid = GlobalSettings::internetSharingConnection();
+    if (uuid.isEmpty()) {
+        return false;
+    }
+
+    const NetworkManager::ActiveConnection::List activeConnections = NetworkManager::activeConnections();
+    return std::any_of(activeConnections.cbegin(), activeConnections.cend(), [&uuid](const NetworkManager::ActiveConnection::Ptr &activeConnection) {
+        return activeConnection->uuid() == uuid;
+    });
+#else
+    return false;
+#endif
+}
+
+void Bluetooth::setInternetSharing(bool enable)
+{
+#if HAVE_NETWORKMANAGERQT
+    NetworkManager::Connection::Ptr connection = NetworkManager::findConnectionByUuid(GlobalSettings::internetSharingConnection());
+
+    if (!enable) {
+        if (connection) {
+            connection->remove();
+        }
+        GlobalSettings::setInternetSharingConnection(QString());
+        GlobalSettings::self()->save();
+        return;
+    }
+
+    if (connection) {
+        activateInternetSharing(connection->path());
+        return;
+    }
+
+    // A bridge with a Bluetooth NAP setting makes NetworkManager register the network
+    // server with BlueZ, and the shared method gives connected devices DHCP and NAT
+    const QString uuid = QUuid::createUuid().toString(QUuid::WithoutBraces);
+    NMVariantMapMap settings;
+    settings[QStringLiteral("connection")] = {
+        {QStringLiteral("id"), i18nc("@title NetworkManager connection name", "Bluetooth Internet Sharing")},
+        {QStringLiteral("uuid"), uuid},
+        {QStringLiteral("type"), QStringLiteral("bridge")},
+        {QStringLiteral("interface-name"), QStringLiteral("pan0")},
+    };
+    settings[QStringLiteral("bridge")] = {{QStringLiteral("stp"), false}};
+    settings[QStringLiteral("bluetooth")] = {{QStringLiteral("type"), QStringLiteral("nap")}};
+    settings[QStringLiteral("ipv4")] = {{QStringLiteral("method"), QStringLiteral("shared")}};
+    settings[QStringLiteral("ipv6")] = {{QStringLiteral("method"), QStringLiteral("ignore")}};
+
+    auto *watcher = new QDBusPendingCallWatcher(NetworkManager::addConnection(settings), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, uuid](QDBusPendingCallWatcher *watcher) {
+        watcher->deleteLater();
+        QDBusPendingReply<QDBusObjectPath> reply = *watcher;
+        if (reply.isError()) {
+            Q_EMIT errorOccured(reply.error().message());
+            Q_EMIT internetSharingChanged();
+            return;
+        }
+
+        GlobalSettings::setInternetSharingConnection(uuid);
+        GlobalSettings::self()->save();
+        activateInternetSharing(reply.value().path());
+    });
+#else
+    Q_UNUSED(enable)
+#endif
+}
+
+void Bluetooth::activateInternetSharing(const QString &connectionPath)
+{
+#if HAVE_NETWORKMANAGERQT
+    auto *watcher = new QDBusPendingCallWatcher(NetworkManager::activateConnection(connectionPath, QString(), QString()), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this](QDBusPendingCallWatcher *watcher) {
+        watcher->deleteLater();
+        QDBusPendingReply<QDBusObjectPath> reply = *watcher;
+        if (reply.isError()) {
+            Q_EMIT errorOccured(reply.error().message());
+        }
+        Q_EMIT internetSharingChanged();
+    });
+#else
+    Q_UNUSED(connectionPath)
+#endif
+}
+
